<template>
  <div class="extra-wrap">
    <template v-if="section==='users'">
      <div class="module-card"><div class="card-heading"><div><h3>新建用户</h3><p>管理员可进入控制台；普通用户只能个性化浏览。</p></div><el-button @click="loadUsers">刷新列表</el-button></div><el-form :model="newUser" class="user-create" @submit.prevent="createUser"><el-input v-model="newUser.username" placeholder="用户名" autocomplete="username" @keyup.enter.prevent="createUser"/><el-input v-model="newUser.password" type="password" show-password placeholder="初始密码（8–200 位）" autocomplete="new-password" @keyup.enter.prevent="createUser"/><el-input v-model="newUser.email" placeholder="登录邮箱（可选）" @keyup.enter.prevent="createUser"/><el-select v-model="newUser.role"><el-option label="普通用户" value="user"/><el-option label="管理员" value="admin"/></el-select><el-button type="primary" :loading="saving" @click="createUser">创建账号</el-button></el-form></div>
      <div class="module-card table-card"><el-table :data="pagedUsers" v-loading="loading" stripe><el-table-column prop="username" label="用户名" min-width="125"/><el-table-column prop="display_name" label="显示名" min-width="120"><template #default="{row}">{{ row.display_name||'—' }}</template></el-table-column><el-table-column label="邮箱" min-width="200"><template #default="{row}"><span>{{ row.email||'未绑定' }}</span><el-tag v-if="row.email" :type="row.email_verified?'success':'warning'" size="small" class="tag-gap">{{ row.email_verified?'已验证':'未验证' }}</el-tag></template></el-table-column><el-table-column label="角色" width="95"><template #default="{row}"><el-tag :type="row.role==='admin'?'danger':'info'" size="small">{{ row.role==='admin'?'管理员':'普通用户' }}</el-tag></template></el-table-column><el-table-column label="状态" width="95"><template #default="{row}"><el-tag :type="row.disabled?'info':'success'" size="small">{{ row.disabled?'已禁用':'正常' }}</el-tag></template></el-table-column><el-table-column label="最近登录" min-width="155"><template #default="{row}">{{ dateTime(row.last_login_at) }}</template></el-table-column><el-table-column label="管理操作" min-width="255" fixed="right"><template #default="{row}"><el-button link @click="editName(row)">改名</el-button><el-button link @click="editEmail(row)">邮箱</el-button><el-button v-if="row.email&&!row.email_verified" link @click="verifyEmail(row)">验证</el-button><el-button link @click="resetPassword(row)">重置密码</el-button><el-button link :type="row.disabled?'success':'danger'" @click="toggleUser(row)">{{ row.disabled?'启用':'禁用' }}</el-button></template></el-table-column></el-table><PaginationBar v-model:page="usersPage" v-model:page-size="usersPageSize" :total="users.length"/></div>
    </template>
    <template v-else-if="section==='recycle'">
      <div class="module-card recycle-summary"><div><span class="muted">回收站</span><strong>{{ recycleGames.length }}</strong><small>款游戏</small></div><p>这里只做逻辑删除。恢复后会重新出现在前台目录，价格与历史数据会保留。</p><el-button @click="loadRecycle">刷新</el-button></div>
      <div class="module-card table-card"><el-table :data="pagedRecycleGames" v-loading="loading" stripe><el-table-column prop="steam_appid" label="AppID" width="110"><template #default="{row}">{{ row.steam_appid||'—' }}</template></el-table-column><el-table-column label="游戏" min-width="220"><template #default="{row}"><strong>{{ row.name }}</strong><small>{{ row.name_en||' ' }}</small></template></el-table-column><el-table-column prop="app_type" label="类型" width="90"/><el-table-column label="平台" min-width="150"><template #default="{row}"><el-tag v-for="p in row.platform_names||[]" :key="p" size="small" class="tag-gap">{{ p }}</el-tag><span v-if="!row.platform_names?.length">—</span></template></el-table-column><el-table-column prop="offer_count" label="报价数" width="90" align="right"/><el-table-column label="删除时间" min-width="155"><template #default="{row}">{{ dateTime(row.deleted_at) }}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="restoreGame(row)">恢复</el-button></template></el-table-column></el-table><PaginationBar v-model:page="recyclePage" v-model:page-size="recyclePageSize" :total="recycleGames.length"/></div>
    </template>
    <template v-else-if="section==='steam'">
      <div class="module-card steam-account">
        <div class="card-heading"><div><h3>绑定的 Steam 账号</h3><p>每个站点用户最多绑定 5 个 Steam 账号，一个 Steam 账号只能属于一个用户；绑定后自动同步游戏库与愿望单。</p></div><div class="steam-actions"><el-button type="primary" :disabled="steamAccounts.length>=steamLimit" @click="bindSteam">{{ steamAccounts.length>=steamLimit?'已达绑定上限':'绑定新账号' }}</el-button><el-button @click="loadSteam">刷新</el-button></div></div>
        <el-alert v-if="steamError" :title="steamError" type="error" :closable="false" class="steam-alert"/>
        <el-table v-if="steamAccounts.length" :data="steamAccounts" stripe>
          <el-table-column label="账号" min-width="220"><template #default="{row}"><div class="steam-account-cell"><img v-if="row.avatar" :src="row.avatar" class="steam-avatar-img" @error="$event.target.style.display='none'"><div><strong>{{ row.alias||row.persona_name||row.steam_id }}</strong><small>{{ row.alias&&row.persona_name?row.persona_name+' · ':'' }}{{ row.steam_id }}</small></div></div></template></el-table-column>
          <el-table-column label="游戏库" width="90" align="right"><template #default="{row}"><el-button link type="primary" @click="toggleLibrary(row)">{{ row.games }}</el-button></template></el-table-column>
          <el-table-column label="愿望单" width="90" align="right"><template #default="{row}">{{ row.wishlist }}</template></el-table-column>
          <el-table-column label="最近同步" min-width="160"><template #default="{row}">{{ dateTime(row.library_synced_at)||'未同步' }}</template></el-table-column>
          <el-table-column label="操作" min-width="330" fixed="right"><template #default="{row}"><el-button link type="primary" @click="syncSteam(row,'library')">同步游戏库</el-button><el-button link @click="syncSteam(row,'wishlist')">同步愿望单</el-button><el-button link @click="editAlias(row)">改别名</el-button><el-button link type="danger" @click="unbindSteam(row)">解绑</el-button></template></el-table-column>
        </el-table>
        <el-empty v-else description="还没有绑定 Steam 账号，点右上角「绑定新账号」开始"/>
      </div>
      <div v-if="unownedAccounts.length" class="module-card table-card">
        <div class="card-heading padded"><div><h3>未归属的 Steam 账号（迁移认领）</h3><p>历史登录留下的账号还没有归属任何站点用户，认领后即可同步游戏库与愿望单。</p></div></div>
        <el-table :data="unownedAccounts" stripe><el-table-column label="账号" min-width="240"><template #default="{row}"><div class="steam-account-cell"><div><strong>{{ row.persona_name||row.steam_id }}</strong><small>{{ row.steam_id }}</small></div></div></template></el-table-column><el-table-column label="已同步游戏" width="120" align="right"><template #default="{row}">{{ row.games }}</template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="claimSteam(row)">认领到当前管理员</el-button></template></el-table-column></el-table>
      </div>
      <div v-if="activeAccount && libraryGames.length" class="module-card table-card">
        <div class="card-heading padded"><div><h3>{{ activeAccount.alias||activeAccount.persona_name||activeAccount.steam_id }} 的游戏库</h3><p>最多显示 500 条，按游玩时长排序。</p></div><el-button text @click="activeAccount=null;libraryGames=[]">收起</el-button></div>
        <el-table :data="pagedSteamGames" v-loading="loading" stripe><el-table-column label="游戏" min-width="260"><template #default="{row}"><div class="game-admin"><img :src="`/img/steam/${row.appid}/capsule_sm_120`" @error="$event.target.style.display='none'"><div><a :href="`https://store.steampowered.com/app/${row.appid}/`" target="_blank" rel="noopener">{{ row.name||`appid:${row.appid}` }}</a><small>AppID {{ row.appid }} · {{ row.in_db?'已在本站目录':'尚未入库' }}</small></div></div></template></el-table-column><el-table-column label="游玩时间" width="155" align="right"><template #default="{row}">{{ Number(row.playtime_minutes||0) }} 分钟 · {{ (Number(row.playtime_minutes||0)/60).toFixed(1) }} 小时</template></el-table-column><el-table-column label="本站最低价" width="130" align="right"><template #default="{row}">{{ price(row.low) }}</template></el-table-column><el-table-column label="最近游玩" min-width="150"><template #default="{row}">{{ dateTime(row.last_played_at) }}</template></el-table-column></el-table>
        <PaginationBar v-model:page="steamPage" v-model:page-size="steamPageSize" :total="libraryGames.length"/>
      </div>
    </template>
    <template v-else-if="section==='mail'">
      <div class="metric-grid"><div class="metric-card"><span>SMTP 状态</span><strong class="status-text" :class="smtp.ready?'good':'warning'">{{ smtp.ready?'已配置':'未配置' }}</strong></div><div class="metric-card"><span>配置来源</span><strong>{{ smtp.source==='database'?'后台设置':'环境变量' }}</strong></div><div class="metric-card"><span>授权密码</span><strong>{{ smtp.hasPassword?'已保存':'未设置' }}</strong></div></div>
      <div class="module-card"><div class="card-heading"><div><h3>发送测试邮件</h3><p>SMTP 配置统一在系统设置 → 邮件与提醒中修改。</p></div><el-button @click="loadMail">刷新状态</el-button></div><div class="mail-test"><el-input v-model="testEmail" placeholder="接收测试邮件的地址" @keyup.enter="sendTestMail"/><el-button type="primary" :loading="saving" @click="sendTestMail">发送测试</el-button></div><el-alert v-if="mailMessage" :title="mailMessage" :type="mailOk?'success':'error'" :closable="false"/><p v-if="smtpTrace" class="smtp-trace">{{ smtpTrace }}</p></div>
      <div class="module-card table-card"><div class="card-heading padded"><div><h3>最近发送记录</h3><p>最多加载最近 500 条</p></div><el-button text @click="loadMail">刷新</el-button></div><el-table :data="pagedMailRecords" v-loading="loading" stripe><el-table-column prop="email" label="收件人" min-width="190"/><el-table-column prop="purpose" label="用途" width="130"/><el-table-column label="结果" min-width="180"><template #default="{row}"><el-tag :type="row.sent_ok?'success':'danger'" size="small">{{ row.sent_ok?'发送成功':'发送失败' }}</el-tag><small v-if="row.error">{{ row.error }}</small></template></el-table-column><el-table-column label="发送时间" min-width="160"><template #default="{row}">{{ dateTime(row.created_at) }}</template></el-table-column><el-table-column label="正文" width="90"><template #default="{row}"><el-button v-if="row.body" link @click="openMail(row)">查看</el-button><span v-else>—</span></template></el-table-column></el-table><PaginationBar v-model:page="mailPage" v-model:page-size="mailPageSize" :total="mailRecords.length"/></div>
      <el-dialog v-model="mailDialog" :title="activeMail?.subject||'邮件正文'" width="min(600px, 92vw)"><p class="muted">{{ activeMail?.email }} · {{ activeMail?.purpose }} · {{ dateTime(activeMail?.created_at) }}</p><pre class="mail-body">{{ activeMail?.body||'无正文' }}</pre><template #footer><el-button :disabled="!mailCode" @click="copyCode">复制验证码</el-button><el-button type="primary" @click="mailDialog=false">关闭</el-button></template></el-dialog>
    </template>
    <template v-else>
      <div class="module-card log-filters"><el-select v-model="logScope" @change="loadLogs"><el-option label="所有模块" value=""/><el-option label="应用" value="app"/><el-option label="Steam 与同步" value="steam"/><el-option label="用户与登录" value="user"/><el-option label="错误" value="error"/></el-select><el-select v-model="logMinutes" @change="loadLogs"><el-option label="全部时间" value="0"/><el-option label="近 15 分钟" value="15"/><el-option label="近 1 小时" value="60"/><el-option label="近 24 小时" value="1440"/></el-select><el-input v-model="logQuery" clearable placeholder="搜索日志内容" @keyup.enter="loadLogs"/><el-button type="primary" @click="loadLogs">刷新日志</el-button><el-checkbox v-model="autoLogs">每 10 秒自动刷新</el-checkbox></div>
      <div class="module-card log-summary"><span>{{ logFiles.join('、')||'日志文件读取中' }}</span><strong>{{ logEntries.length }} 条</strong><el-button text @click="logEntries=[]">清空当前显示</el-button></div><div class="log-list"><article v-for="(entry,index) in pagedLogEntries" :key="entry.ts+'-'+index" class="log-entry" :class="String(entry.level||'info').toLowerCase()"><time>{{ dateTime(entry.ts||entry.time) }}</time><el-tag :type="logTag(entry.level)" size="small">{{ String(entry.level||'info').toUpperCase() }}</el-tag><strong>{{ entry.event||entry.msg||'日志事件' }}</strong><pre>{{ logDetails(entry) }}</pre></article><el-empty v-if="!logEntries.length" description="没有匹配的日志"/><PaginationBar v-model:page="logsPage" v-model:page-size="logsPageSize" :total="logEntries.length"/></div>
    </template>
  </div>
</template>

<script setup>
import { onBeforeUnmount,onMounted,ref,watch } from 'vue';
import PaginationBar from '../components/PaginationBar.vue';
import { useListPagination } from '../composables/useListPagination.js';
import { ElMessage,ElMessageBox } from 'element-plus';
import { fmtDateTime as dateTime } from '../utils/siteTime.js';
const props=defineProps({section:{type:String,required:true}});
const loading=ref(false),saving=ref(false),users=ref([]),recycleGames=ref([]),steamAccounts=ref([]),unownedAccounts=ref([]),steamLimit=ref(5),steamError=ref(''),activeAccount=ref(null),libraryGames=ref([]),smtp=ref({}),mailRecords=ref([]),mailMessage=ref(''),mailOk=ref(false),smtpTrace=ref(''),testEmail=ref(''),mailDialog=ref(false),activeMail=ref(null),mailCode=ref(null),logEntries=ref([]),logFiles=ref([]),logQuery=ref(''),logScope=ref(''),logMinutes=ref('0'),autoLogs=ref(false);
const newUser=ref({username:'',password:'',email:'',role:'user'});
const usersPager=useListPagination(users), recyclePager=useListPagination(recycleGames), steamPager=useListPagination(libraryGames), mailPager=useListPagination(mailRecords), logsPager=useListPagination(logEntries);
const pagedUsers=usersPager.items, usersPage=usersPager.page, usersPageSize=usersPager.pageSize;
const pagedRecycleGames=recyclePager.items, recyclePage=recyclePager.page, recyclePageSize=recyclePager.pageSize;
const pagedSteamGames=steamPager.items, steamPage=steamPager.page, steamPageSize=steamPager.pageSize;
const pagedMailRecords=mailPager.items, mailPage=mailPager.page, mailPageSize=mailPager.pageSize;
const pagedLogEntries=logsPager.items, logsPage=logsPager.page, logsPageSize=logsPager.pageSize;
function api(path,opts={}){return fetch(path,{credentials:'same-origin',...opts,headers:{'content-type':'application/json',...(opts.headers||{})}}).then(async r=>{const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;});}
function body(method,data){return {method,body:JSON.stringify(data)};}
function notify(e){ElMessage.error(e?.message||String(e));}
function price(v){return v==null?'—':`¥${(Number(v)/100).toFixed(2)}`;}
async function act(fn){saving.value=true;try{await fn();}catch(e){notify(e);}finally{saving.value=false;}}
async function loadUsers(){loading.value=true;try{const d=await api('/api/admin/users');users.value=d.users||[];}catch(e){notify(e);}finally{loading.value=false;}}
async function createUser(){if(!newUser.value.username.trim()||newUser.value.password.length<8)return ElMessage.warning('用户名必填，密码至少 8 位');await act(async()=>{const u={...newUser.value,username:newUser.value.username.trim()};await api('/api/admin/users',body('POST',{username:u.username,password:u.password,role:u.role}));if(u.email.trim())await api(`/api/admin/users/${encodeURIComponent(u.username)}/email`,body('POST',{email:u.email.trim()}));newUser.value={username:'',password:'',email:'',role:'user'};ElMessage.success('账号已创建');await loadUsers();});}
async function editName(row){try{const {value}=await ElMessageBox.prompt(`修改 ${row.username} 的显示名；留空清除`,'修改显示名',{inputValue:row.display_name||''});await api(`/api/admin/users/${encodeURIComponent(row.username)}`,body('PATCH',{display_name:value}));await loadUsers();}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function editEmail(row){try{const {value}=await ElMessageBox.prompt('输入登录邮箱；留空解绑','绑定邮箱',{inputValue:row.email||'',inputType:'email'});await api(`/api/admin/users/${encodeURIComponent(row.username)}/email`,body('POST',{email:value.trim()}));ElMessage.success(value.trim()?'邮箱已绑定，需重新验证':'邮箱已解绑');await loadUsers();}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function verifyEmail(row){await act(async()=>{const d=await api(`/api/admin/users/${encodeURIComponent(row.username)}/email/code`,body('POST',{}));const {value}=await ElMessageBox.prompt(`${d.hint||'验证码已发送'}，输入邮件中的 6 位验证码`,'验证邮箱',{inputPattern:/^\d{6}$/,inputErrorMessage:'请输入 6 位验证码'});await api(`/api/admin/users/${encodeURIComponent(row.username)}/email/verify`,body('POST',{code:value.trim()}));ElMessage.success('邮箱已验证');await loadUsers();});}
async function resetPassword(row){try{const {value}=await ElMessageBox.prompt('新密码需要 8–200 位，用户的其他会话会退出','重置密码',{inputType:'password',inputPattern:/^.{8,200}$/,inputErrorMessage:'密码长度需要 8–200 位'});await api(`/api/admin/users/${encodeURIComponent(row.username)}/password`,body('POST',{password:value}));ElMessage.success('密码已重置');}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function toggleUser(row){try{await ElMessageBox.confirm(`${row.disabled?'启用':'禁用'}账号 ${row.username}？`,'确认操作',{type:'warning'});await api(`/api/admin/users/${encodeURIComponent(row.username)}`,body('PATCH',{disabled:!row.disabled}));await loadUsers();}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function loadRecycle(){loading.value=true;try{const d=await api('/api/admin/games/deleted?limit=1000');recycleGames.value=d.games||[];}catch(e){notify(e);}finally{loading.value=false;}}
async function restoreGame(row){await act(async()=>{const path=row.steam_appid?`/api/games/${row.steam_appid}/deleted`:`/api/games/id/${row.id}/deleted`;await api(path,body('POST',{deleted:false}));ElMessage.success('游戏已恢复');await loadRecycle();});}
async function loadSteam(){loading.value=true;try{const d=await api('/api/steam/accounts');steamAccounts.value=d.accounts||[];unownedAccounts.value=d.unowned||[];steamLimit.value=Number(d.limit)||5;if(activeAccount.value){const cur=steamAccounts.value.find((a)=>a.steam_id===activeAccount.value.steam_id);if(!cur){activeAccount.value=null;libraryGames.value=[];}}}catch(e){notify(e);}finally{loading.value=false;}}
function bindSteam(){if(steamAccounts.value.length>=steamLimit.value)return;window.location.href='/api/auth/steam/start';}
async function syncSteam(row,kind){await act(async()=>{const d=await api(`/api/steam/accounts/${encodeURIComponent(row.steam_id)}/${kind}/sync`,body('POST',{}));if(kind==='library')ElMessage.success(`已同步 ${d.total||0} 款游戏（差集清理 ${d.deleted||0} 条）`);else ElMessage.success(`已同步 ${d.total||0} 个愿望单（新增提醒 ${d.watches||0}，目录未命中 ${d.skipped||0}）`);await loadSteam();});}
async function editAlias(row){try{const {value}=await ElMessageBox.prompt('给这个 Steam 账号起个别名（留空清除）','修改别名',{inputValue:row.alias||''});await api(`/api/steam/accounts/${encodeURIComponent(row.steam_id)}`,body('PATCH',{alias:value.trim()}));ElMessage.success('别名已保存');await loadSteam();}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function unbindSteam(row){try{await ElMessageBox.confirm(`解绑「${row.alias||row.persona_name||row.steam_id}」？游戏库与愿望单数据会被删除，愿望单自动提醒一并清理，手动标记保留。`,'确认解绑',{type:'warning'});await api(`/api/steam/accounts/${encodeURIComponent(row.steam_id)}`,body('DELETE',{}));ElMessage.success('已解绑');activeAccount.value=null;libraryGames.value=[];await loadSteam();}catch(e){if(e!=='cancel'&&e!=='close')notify(e);}}
async function claimSteam(row){await act(async()=>{await api(`/api/steam/accounts/${encodeURIComponent(row.steam_id)}/claim`,body('POST',{}));ElMessage.success('已认领到当前管理员，可用「同步游戏库」拉取数据');await loadSteam();});}
async function toggleLibrary(row){if(activeAccount.value?.steam_id===row.steam_id){activeAccount.value=null;libraryGames.value=[];return;}activeAccount.value=row;libraryGames.value=[];loading.value=true;try{const d=await api(`/api/steam/accounts/${encodeURIComponent(row.steam_id)}/library`);libraryGames.value=d.games||[];}catch(e){notify(e);}finally{loading.value=false;}}
function consumeSteamQuery(){if(typeof window==='undefined')return;const q=new URLSearchParams(window.location.search);const err=q.get('steamError');if(err){steamError.value={state:'绑定链接已失效或过期，请重新发起绑定',conflict:'该 Steam 账号已被其他用户绑定',limit:'最多绑定 5 个 Steam 账号',verify:'Steam 校验失败，请重试'}[err]||'绑定失败，请重试';}if(q.get('steamBound'))ElMessage.success('Steam 账号已绑定，正在自动同步游戏库与愿望单');if(err||q.get('steamBound')){q.delete('steamError');q.delete('steamBound');const s=q.toString();history.replaceState(null,'',location.pathname+(s?'?'+s:''));}}
async function loadMail(){loading.value=true;try{const [s,m]=await Promise.all([api('/api/admin/smtp'),api('/api/admin/emails?limit=500')]);smtp.value=s.smtp||{};mailRecords.value=m.records||[];}catch(e){notify(e);}finally{loading.value=false;}}
async function sendTestMail(){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(testEmail.value.trim()))return ElMessage.warning('请输入有效的接收邮箱');mailMessage.value='正在发送…';smtpTrace.value='';await act(async()=>{try{const d=await api('/api/admin/smtp/test',body('POST',{to:testEmail.value.trim()}));mailOk.value=true;mailMessage.value='测试邮件已发送';smtpTrace.value=(d.steps||[]).map(x=>`${x.cmd} → ${x.code}`).join('  |  ');}catch(e){mailOk.value=false;mailMessage.value=e.message;smtpTrace.value=(e.steps||[]).map(x=>`${x.cmd} → ${x.code} ${x.text||''}`).join('\n');throw e;}});await loadMail();}
function openMail(row){activeMail.value=row;mailCode.value=(row.body||'').match(/(\d{6})/)?.[1]||null;mailDialog.value=true;}
async function copyCode(){if(!mailCode.value)return;try{await navigator.clipboard.writeText(mailCode.value);ElMessage.success('验证码已复制');}catch{ElMessage.warning(`复制失败，请手动复制：${mailCode.value}`);}}
async function loadLogs(){loading.value=true;try{const q=new URLSearchParams({limit:'300',grep:logQuery.value.trim(),scope:logScope.value,minutes:logMinutes.value});const d=await api(`/api/admin/logs?${q}`);logEntries.value=(d.entries||[]).slice().reverse();logFiles.value=d.files||[];}catch(e){notify(e);}finally{loading.value=false;}}
function logTag(level){const v=String(level||'').toLowerCase();return v==='error'||v==='fatal'?'danger':v==='warn'||v==='warning'?'warning':'info';}
function logDetails(entry){return Object.entries(entry).filter(([k])=>!['ts','time','level','event','msg'].includes(k)).map(([k,v])=>`${k}=${typeof v==='object'?JSON.stringify(v):v}`).join('  ');}
watch(()=>props.section,s=>{if(s==='users')loadUsers();else if(s==='recycle')loadRecycle();else if(s==='steam'){consumeSteamQuery();loadSteam();}else if(s==='mail')loadMail();else if(s==='sync')loadLogs();});
onMounted(()=>{if(props.section==='users')loadUsers();else if(props.section==='recycle')loadRecycle();else if(props.section==='steam'){consumeSteamQuery();loadSteam();}else if(props.section==='mail')loadMail();else if(props.section==='sync')loadLogs();});
const timer=setInterval(()=>{if(props.section==='sync'&&autoLogs.value&&!document.hidden)loadLogs();},10000);onBeforeUnmount(()=>clearInterval(timer));
</script>

