e{padding:10px;background:var(--panel-2);border-radius:8px;color:var(--fg-muted);font:11px ui-monospace,Consolas,monospace;white-space:pre-wrap}.mail-body{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--panel-2);padding:14px;border-radius:9px;max-height:50vh;overflow:auto;font:12px/1.6 ui-monospace,Consolas,monospace}.log-filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.log-filters>.el-select{width:150px}.log-filters>.el-input{flex:1;min-width:200px}.log-summary{display:flex;align-items:center;gap:12px;color:var(--fg-muted);font-size:10px}.log-summary strong{color:var(--fg)}.log-summary .el-button{margin-left:auto}.log-list{display:grid;gap:7px}.log-entry{display:grid;grid-template-columns:155px 62px minmax(120px,220px) minmax(0,1fr);align-items:start;gap:9px;padding:11px 13px;border:1px solid var(--border);border-left:3px solid var(--fg-subtle);border-radius:9px;background:var(--panel);font-size:10px}.log-entry.error{border-left-color:var(--danger)}.log-entry.warn,.log-entry.warning{border-left-color:var(--warn)}.log-entry time{color:var(--fg-muted)}.log-entry strong{overflow-wrap:anywhere;color:var(--fg)}.log-entry pre{margin:0;color:var(--fg-muted);white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:var(--fg-muted)}
@media(max-width:900px){.user-create{grid-template-columns:repeat(2,minmax(0,1fr))}.metric-grid{grid-template-columns:repeat(3,minmax(100px,1fr))}.log-entry{grid-template-columns:125px 55px minmax(100px,1fr)}}
@media(max-width:560px){.user-create{grid-template-columns:1fr}.user-create>*{width:100%}.recycle-summary{align-items:flex-start;flex-wrap:wrap}.recycle-summary p{flex-basis:100%;margin:0}.steam-account .card-heading{flex-wrap:wrap}.steam-account .steam-actions{width:100%}.mail-test{flex-wrap:wrap}.mail-test>.el-input{flex-basis:100%}.log-filters>.el-select{flex:1;width:auto}.log-filters>.el-input{flex-basis:100%;min-width:0}.log-entry{grid-template-columns:1fr auto;gap:5px}.log-entry strong,.log-entry pre{grid-column:1/-1}}
:global(.admin-content){overflow-y:auto}
